#include "llama.h"
#include "ggml-backend.h"
#include <cstdio>

int main() {
    llama_backend_init();
    ggml_backend_load_all();
    ggml_backend_dev_t gpu = ggml_backend_dev_by_type(GGML_BACKEND_DEVICE_TYPE_GPU);
    if (!gpu) {
        std::fprintf(stderr, "Metal GPU not registered\n");
        return 1;
    }
    std::printf("GPU: %s\n", ggml_backend_dev_description(gpu));
    ggml_backend_t backend = ggml_backend_dev_init(gpu, nullptr);
    if (!backend) {
        std::fprintf(stderr, "Metal initialization failed\n");
        return 1;
    }
    std::printf("Metal backend initialized; %zu devices registered\n", ggml_backend_dev_count());
    ggml_backend_free(backend);
    llama_backend_free();
    return 0;
}

