use anyhow::{Context, Result};
use mistralrs::{Device, GgufModelBuilder, TextMessageRole, TextMessages, TokenSource};

#[tokio::main]
async fn main() -> Result<()> {
    let device = Device::new_metal(0)?;
    println!("Metal available: {}", device.is_metal());
    let Some(path) = std::env::args().nth(1) else {
        println!("Size probe: optionally supply an existing local GGUF to run one chat request.");
        return Ok(());
    };
    // Keep a real local model loader and generation reachable in the executable.
    let path = std::fs::canonicalize(path)?;
    let directory = path.parent().context("Missing model directory")?;
    let filename = path.file_name().context("Missing filename")?.to_string_lossy();
    let model = GgufModelBuilder::new(directory.to_string_lossy(), vec![filename.as_ref()])
        .with_token_source(TokenSource::None)
        .with_max_model_len(8192)
        .with_max_num_seqs(1)
        .with_prefix_cache_n(None)
        .build()
        .await?;
    let messages = TextMessages::new().add_message(TextMessageRole::User, "Reply with OK.");
    let response = model.send_chat_request(messages).await?;
    println!("{:?}", response.choices[0].message.content);
    Ok(())
}
